SourceCode.Declaration:
/// <summary>
/// Contract class for requesting outbound messages via service
/// </summary>
[DataContract]
public class OMGOutboundRequestContract
{
    OMGMessageTypeId    messageTypeId;
    DataAreaId          company;
    boolean             awaitAcknowledgement;

}

Method.Source:
[DataMember('Company')]
public DataAreaId parmCompany(DataAreaId    _company = company)
{
    company = _company;
    return company;
}

[DataMember('MessageTypeId')]
public OMGMessageTypeId parmMessageTypeId(OMGMessageTypeId _messageTypeId  = messageTypeId)
{
    messageTypeId = _messageTypeId;
    return messageTypeId;
}

[DataMember('AwaitAcknowledgement')]
public boolean parmAwaitAcknowledgement(boolean _awaitAcknowledgement = awaitAcknowledgement)
{
    awaitAcknowledgement = _awaitAcknowledgement;

    return awaitAcknowledgement;
}
